diff --git a/apps/desktop/src/renderer/src/lib/components/BranchPicker.svelte b/apps/desktop/src/renderer/src/lib/components/BranchPicker.svelte
index fa7a23d..52afe04 100644
--- a/apps/desktop/src/renderer/src/lib/components/BranchPicker.svelte
+++ b/apps/desktop/src/renderer/src/lib/components/BranchPicker.svelte
@@ -58,6 +58,14 @@
 		prsRequested = false;
 	}

+	// Reset whenever the picker closes. Keying off `open` (rather than the
+	// popover's onOpenChange) covers every close path: checking out a branch,
+	// opening a PR, and the context-menu/dialog actions all close the picker by
+	// setting `open` directly, which never fires onOpenChange.
+	$effect(() => {
+		if (!open) reset();
+	});
+
 	function selectTab(value: string): void {
 		tab = value === 'prs' ? 'prs' : 'branches';
 		// The two lists filter different things; carrying the query across is
@@ -280,12 +288,7 @@
 	const triggerLabel = $derived(viewedPRLabel() ?? viewedBranch() ?? 'no branch');
 </script>

-<Popover.Root
-	bind:open
-	onOpenChange={(v) => {
-		if (!v) reset();
-	}}
->
+<Popover.Root bind:open>
 	<Popover.Trigger
 		disabled={!app.activeRepo}
 		class={cn(buttonVariants({ variant: 'ghost', size: 'sm' }), 'font-normal')}

diff --git a/apps/desktop/src/renderer/src/lib/components/RepoSwitcher.svelte b/apps/desktop/src/renderer/src/lib/components/RepoSwitcher.svelte
index 59d08a3..202d2ce 100644
--- a/apps/desktop/src/renderer/src/lib/components/RepoSwitcher.svelte
+++ b/apps/desktop/src/renderer/src/lib/components/RepoSwitcher.svelte
@@ -25,6 +25,15 @@
 	let open = $state(false);
 	let filter = $state('');

+	// Refresh dirty markers on open and clear the filter on close. Keying off
+	// `open` (rather than the popover's onOpenChange) covers every close path:
+	// selecting a repo, the context-menu actions, and the dialogs all close the
+	// picker by setting `open` directly, which never fires onOpenChange.
+	$effect(() => {
+		if (open) void actions.refreshDirtyRepos();
+		else filter = '';
+	});
+
 	async function pick(id: string): Promise<void> {
 		open = false;
 		await actions.switchRepo(id);
@@ -159,13 +168,7 @@
 	);
 </script>

-<Popover.Root
-	bind:open
-	onOpenChange={(v) => {
-		if (v) void actions.refreshDirtyRepos();
-		else filter = '';
-	}}
->
+<Popover.Root bind:open>
 	<Popover.Trigger class={cn(buttonVariants({ variant: 'ghost', size: 'sm' }), 'max-w-[260px]')}>
 		{#if app.activeRepo?.iconDataUrl}
 			<img src={app.activeRepo.iconDataUrl} alt="" class="size-4 rounded-sm object-contain" />
